referenceSolutions.javascript:
function firstArrivalsBossReceipt(readings, k) {
  const a=readings; let out=[];
  const seen=new Set();for(const x of a)if(!seen.has(x)){seen.add(x);out.push(x);}
  return out.reduce((s,x,i)=>s+(i+1)*x,0);
}

